window.TASK_BANKS[64] = {"version":1,"topicId":64,"tasks":[{"id":"64.1","codeLang":"python","answer":"(3, 2)\n(10, 20, 30)","answerLang":"text","explanation":"Координаты начинаются с нуля; последняя точка — (width-1, height-1), а RGB хранит три канала.","verified":"3.14","wrong":["(2, 3)\n(10, 20, 30)","(3, 2)\n(30, 20, 10)","(3, 2)\n(10, 20, 30, 255)"]},{"id":"64.2","codeLang":"python","answer":"from PIL import Image, ImageOps\nfrom io import BytesIO\ndef make_canvas(width,height,color):\n    return Image.new('RGB',(width,height),color)","answerLang":"python","explanation":"Конструктор получает режим, пару (width,height) и цвет. Новый объект ещё не записан в файл.","verified":"3.14","check":{"append":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef _raises(fn,*args):\n    try:fn(*args)\n    except ValueError:return\n    raise AssertionError('Нужен ValueError для неверного размера')\ndef _snapshot(image):return (image.mode,image.size,image.tobytes())\nfor w,h,color in [(3,2,(12,34,56)),(1,4,(0,0,0)),(5,1,(255,255,255))]:\n    im=make_canvas(w,h,color)\n    assert isinstance(im,Image.Image), 'Верните изображение Pillow'\n    assert im.mode=='RGB' and im.size==(w,h), 'Сохраните режим и порядок размеров'\n    assert all(im.getpixel((x,y))==color for y in range(h) for x in range(w)), 'Залейте весь холст'\nprint('OK')","expect":"OK"}},{"id":"64.3","codeLang":"python","answer":"(4, 2)\nNone","answerLang":"text","explanation":"Вписывание сохраняет пропорции. Возвращаемое значение thumbnail не является миниатюрой: изменился сам source.","verified":"3.14","wrong":["(4, 4)\nNone","(8, 4)\nNone","(8, 4)\n(4, 2)"]},{"id":"64.4","codeLang":"python","answer":"def corners(image):\n    w,h=image.size\n    return [image.getpixel(p) for p in [(0,0),(w-1,0),(0,h-1),(w-1,h-1)]]","answerLang":"python","explanation":"size — число пикселей, поэтому последняя координата на единицу меньше. Для картинки 1×1 все четыре угла совпадают.","verified":"3.14","check":{"append":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef _raises(fn,*args):\n    try:fn(*args)\n    except ValueError:return\n    raise AssertionError('Нужен ValueError для неверного размера')\ndef _snapshot(image):return (image.mode,image.size,image.tobytes())\nfor w,h in [(3,2),(1,1),(2,4)]:\n    im=Image.new('RGB',(w,h)); im.putdata([(i,2*i,3*i) for i in range(w*h)])\n    before=_snapshot(im)\n    expected=[im.getpixel(p) for p in [(0,0),(w-1,0),(0,h-1),(w-1,h-1)]]\n    assert corners(im)==expected, 'Проверьте порядок углов и границы'\n    assert _snapshot(im)==before, 'Источник должен остаться прежним'\nprint('OK')","expect":"OK"}},{"id":"64.5","codeLang":"python","answer":"def small_copy(image,bounds):\n    result=image.copy()\n    result.thumbnail(bounds)\n    return result","answerLang":"python","explanation":"copy отделяет объект, thumbnail ограничивает обе стороны, сохраняя пропорции и не увеличивая небольшую картинку.","verified":"3.14","check":{"append":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef _raises(fn,*args):\n    try:fn(*args)\n    except ValueError:return\n    raise AssertionError('Нужен ValueError для неверного размера')\ndef _snapshot(image):return (image.mode,image.size,image.tobytes())\nfor size,bounds,expected in [((8,4),(4,4),(4,2)),((4,8),(4,4),(2,4)),((1,1),(6,6),(1,1))]:\n    im=Image.new('RGBA',size,(20,30,40,128)); before=_snapshot(im)\n    out=small_copy(im,bounds)\n    assert isinstance(out,Image.Image) and out is not im, 'Нужна самостоятельная копия'\n    assert out.size==expected and out.mode=='RGBA', 'Не растягивайте и не теряйте режим'\n    assert _snapshot(im)==before, 'thumbnail нельзя вызывать на источнике'\nprint('OK')","expect":"OK"}},{"id":"64.6","codeLang":"python","answer":"(255, 255, 255)","answerLang":"text","explanation":"У альфа-канала 0 означает полную прозрачность, 255 — непрозрачность. Простое convert(\"RGB\") не накладывает картинку на белый фон.","verified":"3.14","wrong":["(255, 0, 0)","(0, 0, 0)","(255, 255, 255, 0)"]},{"id":"64.7","codeLang":"python","answer":"from PIL import Image, ImageOps\nfrom io import BytesIO\ndef crop_square(image,side):\n    return ImageOps.fit(image,(side,side),centering=(.5,.5))","answerLang":"python","explanation":"fit заполняет заданную рамку и отрезает лишние края. Это другой контракт, чем thumbnail: у него важна точная квадратная форма.","verified":"3.14","check":{"append":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef _raises(fn,*args):\n    try:fn(*args)\n    except ValueError:return\n    raise AssertionError('Нужен ValueError для неверного размера')\ndef _snapshot(image):return (image.mode,image.size,image.tobytes())\nfor size in [(6,2),(2,6)]:\n    im=Image.new('RGB',size,'red')\n    if size[0]>size[1]:im.paste('green',(2,0,4,2))\n    else:im.paste('green',(0,2,2,4))\n    before=_snapshot(im);out=crop_square(im,2)\n    assert out is not im and out.size==(2,2), 'Верните новый точный квадрат'\n    assert [out.getpixel((x,y)) for y in range(2) for x in range(2)]==[(0,128,0)]*4, 'Обрежьте по центру без растягивания'\n    assert _snapshot(im)==before, 'Не меняйте источник'\nprint('OK')","expect":"OK"}},{"id":"64.8","codeLang":"python","answer":"from PIL import Image, ImageOps\nfrom io import BytesIO\ndef flatten(image,background):\n    front=image.convert('RGBA')\n    back=Image.new('RGBA',front.size,(*background,255))\n    return Image.alpha_composite(back,front).convert('RGB')","answerLang":"python","explanation":"Оба слоя для alpha_composite имеют режим RGBA и один размер. RGB получается после смешивания, а не вместо него.","verified":"3.14","check":{"append":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef _raises(fn,*args):\n    try:fn(*args)\n    except ValueError:return\n    raise AssertionError('Нужен ValueError для неверного размера')\ndef _snapshot(image):return (image.mode,image.size,image.tobytes())\nfor rgba,bg,expected in [((255,0,0,0),(20,30,40),(20,30,40)),((255,0,0,128),(255,255,255),(255,127,127)),((10,20,30,255),(1,2,3),(10,20,30))]:\n    im=Image.new('RGBA',(2,1),rgba);before=_snapshot(im);out=flatten(im,bg)\n    assert out.mode=='RGB' and out.size==im.size and out.getpixel((0,0))==expected, 'Смешайте слои с учётом alpha'\n    assert _snapshot(im)==before, 'Не меняйте источник'\nim=Image.new('RGB',(1,2),(1,2,3));assert flatten(im,(255,255,255)).getpixel((0,1))==(1,2,3)\nprint('OK')","expect":"OK"}},{"id":"64.9","codeLang":"python","answer":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef preview_png(data,bounds=(128,128)):\n    with Image.open(BytesIO(data)) as source:\n        image=ImageOps.exif_transpose(source).convert('RGBA')\n    image.thumbnail(bounds)\n    background=Image.new('RGBA',image.size,'white')\n    result=Image.alpha_composite(background,image).convert('RGB')\n    output=BytesIO()\n    result.save(output,format='PNG')\n    return output.getvalue()","answerLang":"python","explanation":"Открытие, ориентация, размер, прозрачность и кодирование — отдельные решения. В BytesIO нет расширения, поэтому формат PNG надо указать явно. Картинка после exif_transpose отделена от открытого источника.","verified":"3.14","hint":"Проверяйте результат повторным открытием: формат, режим, размеры и несколько пикселей. Отдельно возьмите прозрачный PNG и JPEG с поворотом.","check":{"append":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef _raises(fn,*args):\n    try:fn(*args)\n    except ValueError:return\n    raise AssertionError('Нужен ValueError для неверного размера')\ndef _snapshot(image):return (image.mode,image.size,image.tobytes())\nfor size,bounds,color,expected_size,expected_color in [((8,4),(4,4),(255,0,0,128),(4,2),(255,127,127)),((2,6),(4,3),(10,20,30,255),(1,3),(10,20,30)),((1,1),(8,8),(255,0,0,0),(1,1),(255,255,255))]:\n    image=Image.new('RGBA',size,color);stream=BytesIO();image.save(stream,format='PNG');data=stream.getvalue()\n    result=preview_png(data,bounds)\n    assert type(result) is bytes and result.startswith(b'\\x89PNG'), 'Верните байты PNG'\n    with Image.open(BytesIO(result)) as out:\n        assert out.format=='PNG' and out.mode=='RGB' and out.size==expected_size, 'Проверьте формат, режим и пропорции'\n        assert out.getpixel((0,0))==expected_color, 'Сведите alpha на белый'\nimage=Image.new('RGB',(4,2),'blue');exif=image.getexif();exif[274]=6\nstream=BytesIO();image.save(stream,format='JPEG',exif=exif)\nwith Image.open(BytesIO(preview_png(stream.getvalue(),(4,4)))) as out:\n    assert out.size==(2,4), 'Примените EXIF Orientation до изменения размера'\ntry:preview_png(b'not an image')\nexcept (OSError,ValueError):pass\nelse:raise AssertionError('Повреждённое изображение нельзя скрывать успешным PNG')\nprint('OK')","expect":"OK"}},{"id":"64.10","codeLang":"python","answer":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef contact_sheet(images,columns=3,cell=(64,64),gap=4):\n    if type(columns) is not int or columns<1 or type(gap) is not int or gap<0:\n        raise ValueError('Неверная сетка')\n    if len(cell)!=2 or any(type(v) is not int or v<1 for v in cell):\n        raise ValueError('Неверная ячейка')\n    if not images:return None\n    rows=(len(images)+columns-1)//columns\n    result=Image.new('RGB',(columns*cell[0]+(columns-1)*gap,rows*cell[1]+(rows-1)*gap),'white')\n    for index,source in enumerate(images):\n        image=source.convert('RGBA')\n        image.thumbnail(cell)\n        x=index%columns*(cell[0]+gap)+(cell[0]-image.width)//2\n        y=index//columns*(cell[1]+gap)+(cell[1]-image.height)//2\n        result.paste(image,(x,y),image)\n    return result","answerLang":"python","explanation":"Верхнее округление сохраняет неполный ряд. Промежутки считаются между ячейками, а не вокруг листа. Отдельная RGBA-копия сохраняет источник; маска при paste учитывает прозрачность.","verified":"3.14","hint":"Разберите лист на геометрию сетки, размер миниатюры и положение внутри ячейки. Проверяйте пиксели фона, а не только размеры.","check":{"append":"from PIL import Image, ImageOps\nfrom io import BytesIO\n\ndef _raises(fn,*args):\n    try:fn(*args)\n    except ValueError:return\n    raise AssertionError('Нужен ValueError для неверного размера')\ndef _snapshot(image):return (image.mode,image.size,image.tobytes())\nimages=[Image.new('RGBA',(4,2),(255,0,0,255)),Image.new('RGBA',(2,4),(0,0,255,255)),Image.new('RGBA',(1,1),(0,0,0,0))]\nbefore=[_snapshot(im) for im in images]\nout=contact_sheet(images,columns=2,cell=(4,4),gap=1)\nassert isinstance(out,Image.Image) and out.mode=='RGB' and out.size==(9,9), 'Учтите неполный ряд и промежутки'\nassert out.getpixel((0,0))==(255,255,255) and out.getpixel((0,1))==(255,0,0), 'Центрируйте широкую миниатюру без растягивания'\nassert out.getpixel((6,0))==(0,0,255) and out.getpixel((4,1))==(255,255,255), 'Проверьте высокий источник и промежуток'\nassert out.getpixel((1,6))==(255,255,255), 'Прозрачная картинка должна показать белый фон'\nassert [_snapshot(im) for im in images]==before, 'Не меняйте исходные изображения'\nassert contact_sheet([]) is None, 'Отдельно обработайте пустоту'\nsingle=contact_sheet([Image.new('RGB',(1,1),'green')],columns=1,cell=(3,3),gap=0)\nassert single.size==(3,3) and single.getpixel((1,1))==(0,128,0) and single.getpixel((0,0))==(255,255,255), 'Не увеличивайте маленький источник'\n_raises(contact_sheet,images,0);_raises(contact_sheet,images,True)\n_raises(contact_sheet,images,2,(0,4));_raises(contact_sheet,images,2,(4,4),-1)\nsemi=Image.new('RGBA',(1,1),(255,0,0,128))\nassert contact_sheet([semi],columns=1,cell=(1,1),gap=0).getpixel((0,0))==(255,127,127), 'Смешайте полупрозрачный пиксель с белым фоном'\nlarge=Image.new('RGBA',(8,4),(20,30,40,255));before_large=_snapshot(large)\ncontact_sheet([large],columns=1,cell=(4,4),gap=0)\nassert _snapshot(large)==before_large, 'Уменьшение миниатюры не должно менять большой источник'\nwide=contact_sheet([Image.new('RGB',(1,1),'red')],columns=3,cell=(2,2),gap=2)\nassert wide.size==(10,2), 'Ширина листа сохраняет заданное число столбцов'\nprint('OK')","expect":"OK"}}]};
